export class CoursesComponent {
  apiService;
  courses = [];
  showModal = false;
  editingCourse = null;
  courseForm = {
    title: '',
    description: '',
    thumbnailUrl: '',
    instructorId: null,
    modules: []
  };
  constructor(apiService) {
    this.apiService = apiService;
  }
  ngOnInit() {
    // Ensure modal is closed on initialization
    this.showModal = false;
    this.editingCourse = null;
    console.log('CoursesComponent initialized');
    this.loadCourses();
  }
  loadCourses() {
    this.apiService.get('/api/courses').subscribe({
      next: data => {
        this.courses = data.map(c => ({
          ...c,
          lessonsCount: c.modules?.reduce((sum, m) => sum + (m.lessons?.length || 0), 0) || 0
        }));
      },
      error: err => {
        console.error('Failed to load courses', err);
        this.courses = [];
      }
    });
  }
  openCourseModal() {
    console.log('Opening course modal');
    this.editingCourse = null;
    this.courseForm = {
      title: '',
      description: '',
      thumbnailUrl: '',
      instructorId: null,
      modules: []
    };
    this.showModal = true;
  }
  editCourse(course) {
    console.log('Editing course:', course.id, course.title);
    this.editingCourse = course;
    this.apiService.get(`/api/courses/${course.id}`).subscribe({
      next: data => {
        this.courseForm = {
          title: data.title,
          description: data.description || '',
          thumbnailUrl: data.thumbnailUrl || '',
          instructorId: data.instructorId,
          modules: data.modules?.map(m => ({
            title: m.title,
            description: m.description || '',
            orderIndex: m.orderIndex || 0,
            lessons: m.lessons?.map(l => ({
              title: l.title,
              content: l.content || '',
              videoUrl: l.videoUrl || '',
              orderIndex: l.orderIndex || 0,
              durationMinutes: l.durationMinutes || 0
            })) || []
          })) || []
        };
        this.showModal = true;
      },
      error: err => {
        console.error('Failed to load course details', err);
        alert('Failed to load course details');
      }
    });
  }
  closeModal(event) {
    console.log('Closing modal');
    this.showModal = false;
    this.editingCourse = null;
  }
  addModule() {
    this.courseForm.modules.push({
      title: '',
      description: '',
      orderIndex: this.courseForm.modules.length,
      lessons: []
    });
  }
  removeModule(index) {
    this.courseForm.modules.splice(index, 1);
  }
  addLesson(module) {
    module.lessons.push({
      title: '',
      content: '',
      videoUrl: '',
      orderIndex: module.lessons.length,
      durationMinutes: 0
    });
  }
  removeLesson(module, index) {
    module.lessons.splice(index, 1);
  }
  saveCourse() {
    if (this.editingCourse) {
      this.apiService.put(`/api/courses/${this.editingCourse.id}`, this.courseForm).subscribe({
        next: () => {
          this.loadCourses();
          this.closeModal();
        },
        error: err => {
          console.error('Failed to update course', err);
          alert('Failed to update course: ' + (err.error || 'Unknown error'));
        }
      });
    } else {
      this.apiService.post('/api/courses', this.courseForm).subscribe({
        next: () => {
